//! Implements docs/05-modeling-tools.md §5.16 (parametric parts, milestone
//! 1.10): a part is a group or component whose contents are regenerated by
//! replaying an ordered list of features — each one a registered command
//! with its parameters — inside it.
//!
//! The history lives in the definition's attributes (dictionary
//! [`crate::sketch::DICT`], key [`KEY`], JSON), so documents without parts
//! are unchanged and a part's history undoes like any attribute. Replaying
//! runs each feature as a nested command of the same transaction, with the
//! part as its edit context; `last` then names what the previous feature
//! made, so `face & last` reaches back one step. A string parameter that
//! starts with `=` is a formula of the part's parameters (docs/04 §9.1),
//! evaluated at each regeneration; configurations are named sets of
//! parameter formulas.

use std::collections::BTreeMap;

use glam::DAffine3;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::Value as Json;

use crate::commands::common::{definition_uuid, targets_of};
use crate::commands::organize::parametric::PARAMETERS;
use crate::commands::params::{Target, target_container};
use crate::commands::transaction::AttrTarget;
use crate::commands::{
    Command, CommandCategory, CommandError, CommandMeta, CommandRegistry, CommonParams, Transaction,
};
use crate::document::{
    ComponentDefinition, ContainerRef, Document, Entities, EntityKey, EntityPath, EntityRecord,
    Group, Query, Value,
};
use crate::ids::{DefinitionId, EntityId, Pid};
use crate::params::{FormulaError, Parameters, evaluate};

/// The key of a part's history in the `planyrith` dictionary.
pub const KEY: &str = "part";

/// Commands a feature may not be: they read or write files, change the
/// view only, or edit parts themselves.
const NOT_FEATURES: [&str; 9] = [
    "part-create",
    "feature-add",
    "feature-edit",
    "feature-delete",
    "feature-move",
    "feature-list",
    "part-regenerate",
    "part-configuration",
    "script-eval",
];

/// One step of a part's history.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct Feature {
    /// Its number in the part (stable while it exists).
    pub id: u32,
    /// The command it runs.
    pub command: String,
    /// The command's parameters (strings starting with `=` are formulas).
    pub params: Json,
    /// Its name in the history.
    #[serde(default)]
    pub label: String,
    /// Skipped when regenerating.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub suppressed: bool,
}

/// A part's history.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct History {
    /// Features in order.
    pub features: Vec<Feature>,
    /// Regeneration stops before this feature (rolled back).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub rollback_before: Option<u32>,
    /// Named sets of parameter formulas.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub configurations: BTreeMap<String, BTreeMap<String, String>>,
    /// The configuration last activated.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub active: Option<String>,
}

/// A part found by a query.
struct Part {
    definition: DefinitionId,
    /// The part as an edit context for its features.
    path: EntityPath,
    pid: Pid,
}

/// The part `q` names in the edit context, or with no query the group or
/// component open for editing.
fn find_part(
    tx: &Transaction<'_>,
    target: &Target,
    q: Option<&Query>,
) -> Result<Part, CommandError> {
    let Some(q) = q else {
        let steps = &target.context.path.steps;
        let (Some(&last), ContainerRef::Definition(definition)) = (steps.last(), target.container)
        else {
            return Err(CommandError::invalid_param(
                "part",
                "name the part, or open it for editing",
            ));
        };
        let parent = crate::document::InstancePath {
            steps: steps[..steps.len() - 1].to_vec(),
        };
        let (container, _) = tx
            .document()
            .resolve_container(&parent)
            .map_err(|e| CommandError::NotApplicable(e.to_string()))?;
        let entities = tx
            .document()
            .container(container)
            .ok_or_else(|| CommandError::Internal("parent context vanished".into()))?;
        let id = entities
            .key_to_id(last)
            .ok_or_else(|| CommandError::Internal("open part vanished".into()))?;
        let pid = entities
            .pid_of(id)
            .ok_or_else(|| CommandError::Internal("a group without a pid".into()))?;
        return Ok(Part {
            definition,
            path: EntityPath {
                instances: parent,
                target: EntityKey::Pid(pid),
            },
            pid,
        });
    };
    let ids: Vec<EntityId> = targets_of(tx, target, "part", q)?
        .into_iter()
        .filter(|id| matches!(id, EntityId::Group(_) | EntityId::Instance(_)))
        .collect();
    let [id] = ids.as_slice() else {
        return Err(CommandError::invalid_param(
            "part",
            "must name exactly one group or component",
        ));
    };
    let entities = tx
        .document()
        .container(target.container)
        .ok_or_else(|| CommandError::Internal("edit context vanished".into()))?;
    let definition = entities
        .definition_of(*id)
        .ok_or_else(|| CommandError::Internal("a group without a definition".into()))?;
    let pid = entities
        .pid_of(*id)
        .ok_or_else(|| CommandError::Internal("a group without a pid".into()))?;
    Ok(Part {
        definition,
        path: EntityPath {
            instances: target.context.path.clone(),
            target: EntityKey::Pid(pid),
        },
        pid,
    })
}

/// Whether the definition is a part's (it has a feature history).
pub fn is_part(doc: &Document, d: DefinitionId) -> bool {
    history_of(doc, d).is_some()
}

fn history_of(doc: &Document, d: DefinitionId) -> Option<History> {
    match doc.definition(d)?.attrs.get(crate::sketch::DICT, KEY) {
        Some(Value::Str(json)) => serde_json::from_str(json).ok(),
        _ => None,
    }
}

fn store(tx: &mut Transaction<'_>, d: DefinitionId, h: &History) -> Result<(), CommandError> {
    let json = serde_json::to_string(h).map_err(|e| CommandError::Internal(e.to_string()))?;
    tx.set_attribute(
        AttrTarget::Definition(d),
        crate::sketch::DICT,
        KEY,
        Some(Value::Str(json)),
    )
}

/// The part's parameter formulas.
fn formulas(doc: &Document, d: DefinitionId) -> BTreeMap<String, String> {
    doc.definition(d)
        .and_then(|def| def.attrs.dictionary(PARAMETERS))
        .map(|dict| {
            dict.iter()
                .filter_map(|(k, v)| match v {
                    Value::Str(s) => Some((k.clone(), s.clone())),
                    Value::Float(f) => Some((k.clone(), format!("{f}"))),
                    Value::Int(i) => Some((k.clone(), i.to_string())),
                    Value::Length(l) => Some((k.clone(), format!("{}", l.as_mm()))),
                    _ => None,
                })
                .collect()
        })
        .unwrap_or_default()
}

/// `params` with every `=formula` string replaced by its value.
fn substitute(params: &Json, values: &mut Parameters<'_>) -> Result<Json, FormulaError> {
    Ok(match params {
        Json::String(s) if s.starts_with('=') => {
            let v = evaluate(&s[1..], values)?;
            serde_json::Number::from_f64(v).map_or(Json::Null, Json::Number)
        }
        Json::Array(items) => Json::Array(
            items
                .iter()
                .map(|i| substitute(i, values))
                .collect::<Result<_, _>>()?,
        ),
        Json::Object(map) => Json::Object(
            map.iter()
                .map(|(k, v)| Ok((k.clone(), substitute(v, values)?)))
                .collect::<Result<_, FormulaError>>()?,
        ),
        other => other.clone(),
    })
}

fn check_command(name: &str) -> Result<(), CommandError> {
    let registry = CommandRegistry::with_builtins();
    let command = registry.get(name).ok_or_else(|| {
        CommandError::invalid_param("command", format!("unknown command `{name}`"))
    })?;
    let meta = command.meta();
    if NOT_FEATURES.contains(&name) || meta.view_only || meta.category == CommandCategory::File {
        return Err(CommandError::invalid_param(
            "command",
            format!("`{name}` cannot be a feature"),
        ));
    }
    Ok(())
}

/// Empties the part and replays its features; returns how many ran.
fn regenerate(tx: &mut Transaction<'_>, part: &Part, h: &History) -> Result<usize, CommandError> {
    let registry = CommandRegistry::with_builtins();
    let context =
        serde_json::to_value(&part.path).map_err(|e| CommandError::Internal(e.to_string()))?;
    let container = ContainerRef::Definition(part.definition);
    let empty = tx
        .document()
        .container(container)
        .is_none_or(|c| c.iter().next().is_none());
    if !empty {
        tx.execute_nested(
            &registry,
            "delete",
            serde_json::json!({ "targets": "all", "context": context }),
        )?;
    }
    // Constraints come back with the features that made them.
    tx.set_attribute(
        AttrTarget::Definition(part.definition),
        crate::sketch::DICT,
        crate::sketch::KEY,
        None,
    )?;
    let formulas = formulas(tx.document(), part.definition);
    let mut values = Parameters::new(&formulas);
    let mut ran = 0;
    for f in &h.features {
        if h.rollback_before == Some(f.id) {
            break;
        }
        if f.suppressed {
            continue;
        }
        let mut params = substitute(&f.params, &mut values).map_err(|e| {
            CommandError::NotApplicable(format!("feature {} ({}): {e}", f.id, f.label))
        })?;
        if let Json::Object(map) = &mut params {
            map.insert("context".into(), context.clone());
        } else {
            return Err(CommandError::invalid_param(
                "params",
                format!("feature {}: parameters must be an object", f.id),
            ));
        }
        tx.execute_nested(&registry, &f.command, params)
            .map_err(|e| {
                CommandError::NotApplicable(format!("feature {} ({}) failed: {e}", f.id, f.label))
            })?;
        ran += 1;
    }
    Ok(ran)
}

/// What editing a part's history gave.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct PartOutput {
    /// The part.
    pub part: Pid,
    /// The feature added or changed (when one was).
    pub feature: Option<u32>,
    /// Features in the history.
    pub features: usize,
    /// Features that ran.
    pub ran: usize,
}

fn rerun(
    tx: &mut Transaction<'_>,
    part: &Part,
    h: &History,
    feature: Option<u32>,
) -> Result<PartOutput, CommandError> {
    store(tx, part.definition, h)?;
    let ran = regenerate(tx, part, h)?;
    Ok(PartOutput {
        part: part.pid,
        feature,
        features: h.features.len(),
        ran,
    })
}

fn meta(name: &str, label: &str, view_only: bool) -> CommandMeta {
    CommandMeta {
        name: name.into(),
        label: label.into(),
        category: CommandCategory::Organize,
        view_only,
        steps: Vec::new(),
    }
}

fn not_a_part() -> CommandError {
    CommandError::NotApplicable(
        "that group has no feature history; make it with part-create".into(),
    )
}

// ----- part-create ----------------------------------------------------------------------

/// `part-create` parameters.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct PartCreateParams {
    /// Common fields.
    #[serde(flatten)]
    pub common: CommonParams,
    /// The part's name.
    pub name: String,
    /// A component (shared by its copies, with parameters); `false` makes
    /// a plain group.
    #[serde(default = "yes")]
    pub component: bool,
}

/// The `part-create` command: an empty part with an empty history.
#[derive(Debug, Default, Clone, Copy)]
pub struct PartCreate;

impl Command for PartCreate {
    type Params = PartCreateParams;
    type Output = PartOutput;

    fn name(&self) -> &'static str {
        "part-create"
    }

    fn validate(&self, _: &Document, p: &PartCreateParams) -> Result<(), CommandError> {
        if p.name.trim().is_empty() {
            return Err(CommandError::invalid_param("name", "give the part a name"));
        }
        Ok(())
    }

    fn apply(
        &self,
        tx: &mut Transaction<'_>,
        p: PartCreateParams,
    ) -> Result<PartOutput, CommandError> {
        let target = target_container(tx, &p.common)?;
        let entities = Entities::default();
        let uuid = definition_uuid(tx.document(), &p.name, &entities);
        let mut def = ComponentDefinition::new(uuid, p.name.clone());
        def.is_internal_group = !p.component;
        let definition = tx.insert_definition(def)?;
        let record = if p.component {
            EntityRecord::Instance(crate::document::ComponentInstance {
                definition,
                transform: DAffine3::IDENTITY,
                name: None,
                material_override: None,
                glued_to: None,
                dynamic_attrs: Default::default(),
            })
        } else {
            EntityRecord::Group(Group {
                definition,
                transform: DAffine3::IDENTITY,
                name: p.name.clone(),
            })
        };
        let (_, pid) = tx.insert_entity(target.container, record)?;
        store(tx, definition, &History::default())?;
        Ok(PartOutput {
            part: pid,
            feature: None,
            features: 0,
            ran: 0,
        })
    }

    fn meta(&self) -> CommandMeta {
        meta("part-create", "New Part", false)
    }
}

// ----- feature-add ----------------------------------------------------------------------

/// `feature-add` parameters.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct FeatureAddParams {
    /// Common fields.
    #[serde(flatten)]
    pub common: CommonParams,
    /// The part (one group or component of the edit context); by default
    /// the one open for editing.
    #[serde(default)]
    pub part: Option<Query>,
    /// The command the feature runs.
    pub command: String,
    /// Its parameters (as for the command; `context` is set by the part).
    #[serde(default = "empty_object")]
    #[schemars(with = "BTreeMap<String, serde_json::Value>")]
    pub params: Json,
    /// Its name in the history (the command's label by default).
    #[serde(default)]
    pub label: Option<String>,
    /// Insert before this feature (at the end, or before the rollback
    /// point, by default).
    #[serde(default)]
    pub before: Option<u32>,
}

fn yes() -> bool {
    true
}

fn empty_object() -> Json {
    Json::Object(Default::default())
}

/// The `feature-add` command.
#[derive(Debug, Default, Clone, Copy)]
pub struct FeatureAdd;

impl Command for FeatureAdd {
    type Params = FeatureAddParams;
    type Output = PartOutput;

    fn name(&self) -> &'static str {
        "feature-add"
    }

    fn validate(&self, _: &Document, p: &FeatureAddParams) -> Result<(), CommandError> {
        check_command(&p.command)?;
        if !p.params.is_object() {
            return Err(CommandError::invalid_param("params", "must be an object"));
        }
        Ok(())
    }

    fn apply(
        &self,
        tx: &mut Transaction<'_>,
        p: FeatureAddParams,
    ) -> Result<PartOutput, CommandError> {
        let target = target_container(tx, &p.common)?;
        let part = find_part(tx, &target, p.part.as_ref())?;
        let mut h = history_of(tx.document(), part.definition).ok_or_else(not_a_part)?;
        let id = h.features.iter().map(|f| f.id).max().map_or(1, |m| m + 1);
        let label = p.label.unwrap_or_else(|| {
            CommandRegistry::with_builtins()
                .get(&p.command)
                .map(|c| c.meta().label)
                .unwrap_or_else(|| p.command.clone())
        });
        let mut params = p.params;
        if let Json::Object(map) = &mut params {
            map.remove("context");
        }
        let feature = Feature {
            id,
            command: p.command,
            params,
            label,
            suppressed: false,
        };
        let at = match p.before.or(h.rollback_before) {
            Some(before) => h
                .features
                .iter()
                .position(|f| f.id == before)
                .ok_or_else(|| {
                    CommandError::invalid_param("before", format!("no feature {before}"))
                })?,
            None => h.features.len(),
        };
        h.features.insert(at, feature);
        rerun(tx, &part, &h, Some(id))
    }

    fn meta(&self) -> CommandMeta {
        meta("feature-add", "Add Feature", false)
    }
}

// ----- feature-edit ---------------------------------------------------------------------

/// `feature-edit` parameters.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct FeatureEditParams {
    /// Common fields.
    #[serde(flatten)]
    pub common: CommonParams,
    /// The part; by default the one open for editing.
    #[serde(default)]
    pub part: Option<Query>,
    /// The feature's number.
    pub id: u32,
    /// Parameters to change (merged into the feature's; `null` removes one).
    #[serde(default)]
    #[schemars(with = "Option<BTreeMap<String, serde_json::Value>>")]
    pub params: Option<Json>,
    /// A new name.
    #[serde(default)]
    pub label: Option<String>,
    /// Suppress (true) or restore (false) the feature.
    #[serde(default)]
    pub suppressed: Option<bool>,
}

/// The `feature-edit` command.
#[derive(Debug, Default, Clone, Copy)]
pub struct FeatureEdit;

impl Command for FeatureEdit {
    type Params = FeatureEditParams;
    type Output = PartOutput;

    fn name(&self) -> &'static str {
        "feature-edit"
    }

    fn validate(&self, _: &Document, p: &FeatureEditParams) -> Result<(), CommandError> {
        if p.params.as_ref().is_some_and(|v| !v.is_object()) {
            return Err(CommandError::invalid_param("params", "must be an object"));
        }
        Ok(())
    }

    fn apply(
        &self,
        tx: &mut Transaction<'_>,
        p: FeatureEditParams,
    ) -> Result<PartOutput, CommandError> {
        let target = target_container(tx, &p.common)?;
        let part = find_part(tx, &target, p.part.as_ref())?;
        let mut h = history_of(tx.document(), part.definition).ok_or_else(not_a_part)?;
        let f = h
            .features
            .iter_mut()
            .find(|f| f.id == p.id)
            .ok_or_else(|| CommandError::invalid_param("id", format!("no feature {}", p.id)))?;
        if let (Some(Json::Object(changes)), Json::Object(params)) = (p.params, &mut f.params) {
            for (k, v) in changes {
                if k == "context" {
                    continue;
                }
                if v.is_null() {
                    params.remove(&k);
                } else {
                    params.insert(k, v);
                }
            }
        }
        if let Some(label) = p.label {
            f.label = label;
        }
        if let Some(s) = p.suppressed {
            f.suppressed = s;
        }
        rerun(tx, &part, &h, Some(p.id))
    }

    fn meta(&self) -> CommandMeta {
        meta("feature-edit", "Edit Feature", false)
    }
}

// ----- feature-delete -------------------------------------------------------------------

/// `feature-delete` parameters.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct FeatureDeleteParams {
    /// Common fields.
    #[serde(flatten)]
    pub common: CommonParams,
    /// The part; by default the one open for editing.
    #[serde(default)]
    pub part: Option<Query>,
    /// The features' numbers.
    pub ids: Vec<u32>,
}

/// The `feature-delete` command.
#[derive(Debug, Default, Clone, Copy)]
pub struct FeatureDelete;

impl Command for FeatureDelete {
    type Params = FeatureDeleteParams;
    type Output = PartOutput;

    fn name(&self) -> &'static str {
        "feature-delete"
    }

    fn validate(&self, _: &Document, p: &FeatureDeleteParams) -> Result<(), CommandError> {
        if p.ids.is_empty() {
            return Err(CommandError::invalid_param(
                "ids",
                "name at least one feature",
            ));
        }
        Ok(())
    }

    fn apply(
        &self,
        tx: &mut Transaction<'_>,
        p: FeatureDeleteParams,
    ) -> Result<PartOutput, CommandError> {
        let target = target_container(tx, &p.common)?;
        let part = find_part(tx, &target, p.part.as_ref())?;
        let mut h = history_of(tx.document(), part.definition).ok_or_else(not_a_part)?;
        for id in &p.ids {
            if !h.features.iter().any(|f| f.id == *id) {
                return Err(CommandError::invalid_param(
                    "ids",
                    format!("no feature {id}"),
                ));
            }
        }
        if h.rollback_before.is_some_and(|r| p.ids.contains(&r)) {
            h.rollback_before = None;
        }
        h.features.retain(|f| !p.ids.contains(&f.id));
        rerun(tx, &part, &h, None)
    }

    fn meta(&self) -> CommandMeta {
        meta("feature-delete", "Delete Features", false)
    }
}

// ----- feature-move ---------------------------------------------------------------------

/// `feature-move` parameters.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct FeatureMoveParams {
    /// Common fields.
    #[serde(flatten)]
    pub common: CommonParams,
    /// The part; by default the one open for editing.
    #[serde(default)]
    pub part: Option<Query>,
    /// The feature to move.
    pub id: u32,
    /// Put it before this feature (at the end when absent).
    #[serde(default)]
    pub before: Option<u32>,
}

/// The `feature-move` command: reorders the history.
#[derive(Debug, Default, Clone, Copy)]
pub struct FeatureMove;

impl Command for FeatureMove {
    type Params = FeatureMoveParams;
    type Output = PartOutput;

    fn name(&self) -> &'static str {
        "feature-move"
    }

    fn validate(&self, _: &Document, p: &FeatureMoveParams) -> Result<(), CommandError> {
        if p.before == Some(p.id) {
            return Err(CommandError::invalid_param(
                "before",
                "a feature cannot go before itself",
            ));
        }
        Ok(())
    }

    fn apply(
        &self,
        tx: &mut Transaction<'_>,
        p: FeatureMoveParams,
    ) -> Result<PartOutput, CommandError> {
        let target = target_container(tx, &p.common)?;
        let part = find_part(tx, &target, p.part.as_ref())?;
        let mut h = history_of(tx.document(), part.definition).ok_or_else(not_a_part)?;
        let from = h
            .features
            .iter()
            .position(|f| f.id == p.id)
            .ok_or_else(|| CommandError::invalid_param("id", format!("no feature {}", p.id)))?;
        let f = h.features.remove(from);
        let to =
            match p.before {
                Some(b) => h.features.iter().position(|f| f.id == b).ok_or_else(|| {
                    CommandError::invalid_param("before", format!("no feature {b}"))
                })?,
                None => h.features.len(),
            };
        h.features.insert(to, f);
        rerun(tx, &part, &h, Some(p.id))
    }

    fn meta(&self) -> CommandMeta {
        meta("feature-move", "Reorder Feature", false)
    }
}

// ----- feature-list ---------------------------------------------------------------------

/// `feature-list` parameters.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct FeatureListParams {
    /// Common fields.
    #[serde(flatten)]
    pub common: CommonParams,
    /// The part; by default the one open for editing.
    #[serde(default)]
    pub part: Option<Query>,
}

/// `feature-list` output.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct FeatureListOutput {
    /// The part.
    pub part: Pid,
    /// Its history.
    pub history: History,
    /// Its parameters' values.
    pub parameters: BTreeMap<String, f64>,
}

/// The `feature-list` command.
#[derive(Debug, Default, Clone, Copy)]
pub struct FeatureList;

impl Command for FeatureList {
    type Params = FeatureListParams;
    type Output = FeatureListOutput;

    fn name(&self) -> &'static str {
        "feature-list"
    }

    fn validate(&self, _: &Document, _: &FeatureListParams) -> Result<(), CommandError> {
        Ok(())
    }

    fn apply(
        &self,
        tx: &mut Transaction<'_>,
        p: FeatureListParams,
    ) -> Result<FeatureListOutput, CommandError> {
        let target = target_container(tx, &p.common)?;
        let part = find_part(tx, &target, p.part.as_ref())?;
        let history = history_of(tx.document(), part.definition).ok_or_else(not_a_part)?;
        let formulas = formulas(tx.document(), part.definition);
        let parameters = Parameters::new(&formulas)
            .all()
            .map_err(|e| CommandError::NotApplicable(e.to_string()))?;
        Ok(FeatureListOutput {
            part: part.pid,
            history,
            parameters,
        })
    }

    fn meta(&self) -> CommandMeta {
        meta("feature-list", "List Features", true)
    }
}

// ----- part-regenerate ------------------------------------------------------------------

/// `part-regenerate` parameters.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct PartRegenerateParams {
    /// Common fields.
    #[serde(flatten)]
    pub common: CommonParams,
    /// The part; by default the one open for editing.
    #[serde(default)]
    pub part: Option<Query>,
    /// Roll back: stop before this feature from now on.
    #[serde(default)]
    pub rollback_before: Option<u32>,
    /// Roll forward: replay every feature again.
    #[serde(default)]
    pub roll_forward: bool,
}

/// The `part-regenerate` command: replays the history (after parameters
/// changed), optionally rolling back or forward.
#[derive(Debug, Default, Clone, Copy)]
pub struct PartRegenerate;

impl Command for PartRegenerate {
    type Params = PartRegenerateParams;
    type Output = PartOutput;

    fn name(&self) -> &'static str {
        "part-regenerate"
    }

    fn validate(&self, _: &Document, p: &PartRegenerateParams) -> Result<(), CommandError> {
        if p.rollback_before.is_some() && p.roll_forward {
            return Err(CommandError::invalid_param(
                "roll_forward",
                "roll back or forward, not both",
            ));
        }
        Ok(())
    }

    fn apply(
        &self,
        tx: &mut Transaction<'_>,
        p: PartRegenerateParams,
    ) -> Result<PartOutput, CommandError> {
        let target = target_container(tx, &p.common)?;
        let part = find_part(tx, &target, p.part.as_ref())?;
        let mut h = history_of(tx.document(), part.definition).ok_or_else(not_a_part)?;
        if let Some(r) = p.rollback_before {
            if !h.features.iter().any(|f| f.id == r) {
                return Err(CommandError::invalid_param(
                    "rollback_before",
                    format!("no feature {r}"),
                ));
            }
            h.rollback_before = Some(r);
        }
        if p.roll_forward {
            h.rollback_before = None;
        }
        rerun(tx, &part, &h, None)
    }

    fn meta(&self) -> CommandMeta {
        meta("part-regenerate", "Regenerate Part", false)
    }
}

// ----- part-configuration ---------------------------------------------------------------

/// `part-configuration` parameters.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct PartConfigurationParams {
    /// Common fields.
    #[serde(flatten)]
    pub common: CommonParams,
    /// The part; by default the one open for editing.
    #[serde(default)]
    pub part: Option<Query>,
    /// The configuration's name.
    pub name: String,
    /// Define (or redefine) it with these parameter formulas.
    #[serde(default)]
    pub values: Option<BTreeMap<String, String>>,
    /// Make it current: its formulas become the part's parameters, and the
    /// part regenerates.
    #[serde(default)]
    pub activate: bool,
    /// Remove it.
    #[serde(default)]
    pub remove: bool,
}

/// The `part-configuration` command.
#[derive(Debug, Default, Clone, Copy)]
pub struct PartConfiguration;

impl Command for PartConfiguration {
    type Params = PartConfigurationParams;
    type Output = PartOutput;

    fn name(&self) -> &'static str {
        "part-configuration"
    }

    fn validate(&self, _: &Document, p: &PartConfigurationParams) -> Result<(), CommandError> {
        if p.name.trim().is_empty() {
            return Err(CommandError::invalid_param(
                "name",
                "give the configuration a name",
            ));
        }
        if p.remove && (p.activate || p.values.is_some()) {
            return Err(CommandError::invalid_param("remove", "remove alone"));
        }
        if !p.remove && !p.activate && p.values.is_none() {
            return Err(CommandError::invalid_param(
                "values",
                "give values, activate or remove",
            ));
        }
        Ok(())
    }

    fn apply(
        &self,
        tx: &mut Transaction<'_>,
        p: PartConfigurationParams,
    ) -> Result<PartOutput, CommandError> {
        let target = target_container(tx, &p.common)?;
        let part = find_part(tx, &target, p.part.as_ref())?;
        let mut h = history_of(tx.document(), part.definition).ok_or_else(not_a_part)?;
        if p.remove {
            if h.configurations.remove(&p.name).is_none() {
                return Err(CommandError::invalid_param(
                    "name",
                    format!("no configuration {}", p.name),
                ));
            }
            if h.active.as_deref() == Some(p.name.as_str()) {
                h.active = None;
            }
            store(tx, part.definition, &h)?;
            return Ok(PartOutput {
                part: part.pid,
                feature: None,
                features: h.features.len(),
                ran: 0,
            });
        }
        if let Some(values) = p.values {
            for formula in values.values() {
                evaluate(formula, &mut NoNames)
                    .or_else(|e| {
                        if e.0.starts_with("unknown parameter") {
                            Ok(0.0)
                        } else {
                            Err(e)
                        }
                    })
                    .map_err(|e| CommandError::invalid_param("values", e.to_string()))?;
            }
            h.configurations.insert(p.name.clone(), values);
        }
        if !p.activate {
            store(tx, part.definition, &h)?;
            return Ok(PartOutput {
                part: part.pid,
                feature: None,
                features: h.features.len(),
                ran: 0,
            });
        }
        let values = h.configurations.get(&p.name).cloned().ok_or_else(|| {
            CommandError::invalid_param("name", format!("no configuration {}", p.name))
        })?;
        for (name, formula) in values {
            tx.set_attribute(
                AttrTarget::Definition(part.definition),
                PARAMETERS,
                &name,
                Some(Value::Str(formula)),
            )?;
        }
        h.active = Some(p.name);
        rerun(tx, &part, &h, None)
    }

    fn meta(&self) -> CommandMeta {
        meta("part-configuration", "Part Configuration", false)
    }
}

/// Parameters for syntax checks only: every name is unknown.
struct NoNames;

impl crate::params::Names for NoNames {
    fn value(&mut self, name: &str) -> Result<f64, FormulaError> {
        Err(FormulaError(format!("unknown parameter `{name}`")))
    }
}

/// Registers the part commands.
pub fn register(registry: &mut CommandRegistry) {
    registry.register(PartCreate);
    registry.register(FeatureAdd);
    registry.register(FeatureEdit);
    registry.register(FeatureDelete);
    registry.register(FeatureMove);
    registry.register(FeatureList);
    registry.register(PartRegenerate);
    registry.register(PartConfiguration);
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use crate::commands::{CommandRegistry, Engine};
    use crate::document::Document;
    use serde_json::json;
    use std::sync::Arc;

    fn engine() -> Engine {
        Engine::new(Document::new(), Arc::new(CommandRegistry::with_builtins()))
    }

    fn volume(e: &mut Engine) -> f64 {
        e.execute_erased("mass-properties", json!({})).unwrap()["total"]["volume_mm3"]
            .as_f64()
            .unwrap()
    }

    /// A plate with a parametric height and a hole, regenerated when the
    /// parameters change, edited, suppressed, rolled back and reordered.
    #[test]
    fn a_parametric_plate_regenerates() {
        let mut e = engine();
        e.execute_erased("part-create", json!({ "name": "Plate", "component": true }))
            .unwrap();
        e.execute_erased(
            "parameter-set",
            json!({ "component": "Plate", "name": "height", "formula": "20" }),
        )
        .unwrap();
        e.execute_erased(
            "feature-add",
            json!({ "part": "instance", "command": "rectangle",
                    "params": { "corner_a": [0, 0, 0], "corner_b": [400, 200, 0] } }),
        )
        .unwrap();
        e.execute_erased(
            "feature-add",
            json!({ "part": "instance", "command": "push-pull",
                    "params": { "face": { "Query": "face & last" }, "distance": "=height" } }),
        )
        .unwrap();
        assert!((volume(&mut e) - 400.0 * 200.0 * 20.0).abs() < 1e-6);

        // A new height regenerates the plate.
        e.execute_erased(
            "parameter-set",
            json!({ "component": "Plate", "name": "height", "formula": "35" }),
        )
        .unwrap();
        e.execute_erased("part-regenerate", json!({ "part": "instance" }))
            .unwrap();
        assert!((volume(&mut e) - 400.0 * 200.0 * 35.0).abs() < 1e-6);

        // A feature's parameters change; undo restores the previous solid.
        e.execute_erased(
            "feature-edit",
            json!({ "part": "instance", "id": 1,
                    "params": { "corner_b": [300, 200, 0] } }),
        )
        .unwrap();
        assert!((volume(&mut e) - 300.0 * 200.0 * 35.0).abs() < 1e-6);
        e.undo().unwrap();
        assert!((volume(&mut e) - 400.0 * 200.0 * 35.0).abs() < 1e-6);

        // Suppressing the extrusion leaves the flat sketch; rolling back
        // before it does too; rolling forward brings it back.
        e.execute_erased(
            "feature-edit",
            json!({ "part": "instance", "id": 2, "suppressed": true }),
        )
        .unwrap();
        assert_eq!(volume(&mut e), 0.0);
        e.execute_erased(
            "feature-edit",
            json!({ "part": "instance", "id": 2, "suppressed": false }),
        )
        .unwrap();
        e.execute_erased(
            "part-regenerate",
            json!({ "part": "instance", "rollback_before": 2 }),
        )
        .unwrap();
        assert_eq!(volume(&mut e), 0.0);
        e.execute_erased(
            "part-regenerate",
            json!({ "part": "instance", "roll_forward": true }),
        )
        .unwrap();
        assert!(volume(&mut e) > 0.0);

        // Configurations set the parameters.
        e.execute_erased(
            "part-configuration",
            json!({ "part": "instance", "name": "Thin", "values": { "height": "5" }, "activate": true }),
        )
        .unwrap();
        assert!((volume(&mut e) - 400.0 * 200.0 * 5.0).abs() < 1e-6);
        let list = e
            .execute_erased("feature-list", json!({ "part": "instance" }))
            .unwrap();
        assert_eq!(list["history"]["active"], "Thin");
        assert_eq!(list["parameters"]["height"], 5.0);
        assert_eq!(list["history"]["features"].as_array().unwrap().len(), 2);

        // A failing feature fails the edit and changes nothing.
        let err = e
            .execute_erased(
                "feature-edit",
                json!({ "part": "instance", "id": 2, "params": { "face": { "Query": "face & last & plane:xy@999" } } }),
            )
            .unwrap_err();
        assert!(err.to_string().contains("feature 2"), "{err}");
        assert!((volume(&mut e) - 400.0 * 200.0 * 5.0).abs() < 1e-6);

        // Deleting the extrusion; features that cannot be features.
        e.execute_erased("feature-delete", json!({ "part": "instance", "ids": [2] }))
            .unwrap();
        assert_eq!(volume(&mut e), 0.0);
        assert!(
            e.execute_erased(
                "feature-add",
                json!({ "part": "instance", "command": "save", "params": {} })
            )
            .is_err()
        );
    }

    /// Inside the open part, the part needs no naming: features recorded
    /// while editing it.
    #[test]
    fn features_of_the_part_open_for_editing() {
        let mut e = engine();
        let out = e
            .execute_erased("part-create", json!({ "name": "Block" }))
            .unwrap();
        let pid = out["part"].as_u64().unwrap();
        e.set_context(crate::document::EditContext {
            path: crate::document::InstancePath::root()
                .child(crate::document::EntityKey::Pid(crate::ids::Pid(pid))),
        })
        .unwrap();
        e.execute_erased(
            "feature-add",
            json!({ "command": "rectangle",
                    "params": { "corner_a": [0, 0, 0], "corner_b": [100, 100, 0] } }),
        )
        .unwrap();
        e.execute_erased(
            "feature-add",
            json!({ "command": "push-pull",
                    "params": { "face": { "Query": "face & last" }, "distance": 50 } }),
        )
        .unwrap();
        let list = e.execute_erased("feature-list", json!({})).unwrap();
        assert_eq!(list["history"]["features"].as_array().unwrap().len(), 2);
        assert!((volume(&mut e) - 500_000.0).abs() < 1e-6);
        // Outside any part, a part must be named.
        e.set_context(crate::document::EditContext::model())
            .unwrap();
        assert!(e.execute_erased("feature-list", json!({})).is_err());
    }
}
